-- Validate complete posted handoffs at COMMIT, after the replacement is posted.
ALTER TABLE finance_billing_corrections ADD CONSTRAINT finance_billing_posted_amounts CHECK(status<>'posted' OR (credited_minor IS NOT NULL AND refund_minor IS NOT NULL AND credited_minor+refund_minor=total_minor));
CREATE FUNCTION validate_finance_billing_correction_handoff() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE c finance_billing_corrections; parent finance_business_billing_runs; original finance_invoices; replacement finance_business_billing_runs; credit finance_journals; BEGIN
 SELECT * INTO c FROM finance_billing_corrections WHERE id=NEW.id;
 IF c.status<>'posted' THEN RETURN NEW;END IF;
 SELECT * INTO parent FROM finance_business_billing_runs WHERE id=c.billing_run_id;
 SELECT * INTO original FROM finance_invoices WHERE id=c.invoice_id;
 SELECT * INTO replacement FROM finance_business_billing_runs WHERE id=c.replacement_bill_id;
 SELECT * INTO credit FROM finance_journals WHERE id=c.credit_journal_id;
 IF parent.company_id IS DISTINCT FROM c.company_id OR parent.invoice_id IS DISTINCT FROM original.id OR original.company_id IS DISTINCT FROM c.company_id OR original.status IS DISTINCT FROM 'paid' OR original.outstanding_minor<>0 OR original.base_outstanding_minor<>0 OR (original.subtotal_minor,original.tax_minor,original.total_minor) IS DISTINCT FROM (c.subtotal_minor,c.tax_minor,c.total_minor) OR (replacement.company_id,replacement.parent_run_id) IS DISTINCT FROM (c.company_id,parent.id) OR (credit.company_id,credit.source_type,credit.source_id,credit.status,credit.period_id,credit.entry_date) IS DISTINCT FROM (c.company_id,'business_billing_credit',c.id,'posted',c.period_id,c.entry_date) OR EXISTS(SELECT 1 FROM finance_recognition_runs r WHERE r.billing_run_id=parent.id AND r.status IN ('draft','posted')) THEN RAISE EXCEPTION 'BILLING_CORRECTION_HANDOFF_INVALID' USING ERRCODE='23514';END IF;
 IF c.total_minor IS DISTINCT FROM (SELECT SUM(l.credit_minor-l.debit_minor) FROM finance_journal_lines l WHERE l.journal_id=credit.id AND l.account_id=original.debit_account_id) OR c.total_minor IS DISTINCT FROM (SELECT SUM(l.base_credit_minor-l.base_debit_minor) FROM finance_journal_lines l WHERE l.journal_id=credit.id AND l.account_id=original.debit_account_id) THEN RAISE EXCEPTION 'BILLING_CREDIT_CONTROL_MISMATCH' USING ERRCODE='23514';END IF;
 IF replacement.invoice_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM finance_invoices i JOIN finance_journals j ON j.id=i.journal_id AND j.company_id=i.company_id WHERE i.id=replacement.invoice_id AND i.company_id=c.company_id AND i.status='posted' AND j.status='posted' AND j.entry_date=c.entry_date) OR replacement.invoice_id IS NULL AND replacement.no_charge_status IS DISTINCT FROM 'approved' THEN RAISE EXCEPTION 'BILLING_REPLACEMENT_NOT_POSTED' USING ERRCODE='23514';END IF;
 IF c.refund_minor>0 AND NOT EXISTS(SELECT 1 FROM finance_refund_obligations o WHERE o.billing_correction_id=c.id AND o.company_id=c.company_id AND o.invoice_id=original.id AND o.party_id=original.party_id AND o.balance_account_id=original.debit_account_id AND o.currency=original.currency AND o.direction='outgoing' AND o.amount_minor=c.refund_minor AND o.base_amount_minor=c.refund_minor AND o.source_credit_journal_id=credit.id) OR c.refund_minor=0 AND EXISTS(SELECT 1 FROM finance_refund_obligations WHERE billing_correction_id=c.id) THEN RAISE EXCEPTION 'BILLING_REFUND_HANDOFF_INVALID' USING ERRCODE='23514';END IF;
 RETURN NEW;END;$$;
CREATE CONSTRAINT TRIGGER finance_billing_correction_complete AFTER INSERT OR UPDATE ON finance_billing_corrections DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_finance_billing_correction_handoff();
